SELECT FROM base_product p JOIN base_vendor v ON v.vendor_id = p.vendor_id
AND p.vendor_id = #{vendorId}
AND p.use_yn = #{useYn}
AND (p.part_no LIKE CONCAT('%', #{keyword}, '%') OR p.product_name LIKE CONCAT('%', #{keyword}, '%') OR p.product_code LIKE CONCAT('%', #{keyword}, '%'))
ORDER BY p.product_code ASC

SELECT * FROM base_product
WHERE vendor_id = #{vendorId} AND part_no = #{partNo}

    AND product_id != #{excludeId}

LIMIT 1

SELECT COUNT(*) FROM base_product
WHERE vendor_id IN
#{id}
